Provides production-grade model versioning with stage management
(staging/production), automatic comparison, and artifact tracking.
"""

from typing import Any, Dict, List, Optional, Union
import json
import hashlib
from pathlib import Path
from datetime import datetime
from dataclasses import dataclass, field, asdict
import pickle


@dataclass
class ModelMetadata:
    """Metadata for a registered model."""
    model_id: str
    name: str
    version: str
    stage: str = "staging"
    created_at: str = field(default_factory=lambda: datetime.now().isoformat())
    metrics: Dict[str, float] = field(default_factory=dict)
    parameters: Dict[str, Any] = field(default_factory=dict)
    tags: Dict[str, str] = field(default_factory=dict)
    signature: Optional[str] = None
    parent_version: Optional[str] = None
    artifact_path: Optional[str] = None
    framework: Optional[str] = None

    def to_dict(self) -> Dict:
        return asdict(self)

    @classmethod
    def from_dict(cls, data: Dict) -> "ModelMetadata":
        return cls(**data)


class LocalModelRegistry:
    """Local filesystem-based model registry."""

    def __init__(self, registry_path: str = "./model_registry"):
        self.registry_path = Path(registry_path)
        self.registry_path.mkdir(parents=True, exist_ok=True)
        self.models_file = self.registry_path / "registry.json"
        self.versions: Dict[str, List[ModelMetadata]] = {}
        self._load_registry()

    def _load_registry(self):
        """Load registry from disk."""
        if self.models_file.exists():
            try:
                with open(self.models_file, 'r') as f:
                    data = json.load(f)
                    for name, versions in data.items():
                        self.versions[name] = [ModelMetadata.from_dict(v) for v in versions]
            except Exception:
                self.versions = {}
        else:
            self.versions = {}

    def _save_registry(self):
        """Save registry to disk."""
        data = {}
        for name, versions in self.versions.items():
            data[name] = [v.to_dict() for v in versions]
        with open(self.models_file, 'w') as f:
            json.dump(data, f, indent=2)

    def _generate_id(self, name: str, content: bytes) -> str:
        """Generate unique model ID."""
        hash_input = f"{name}:{datetime.now().isoformat()}:{content[:100]}"
        return hashlib.md5(hash_input.encode()).hexdigest()[:12]

    def register(
        self,
        model: Any,
        name: str,
        metrics: Optional[Dict[str, float]] = None,
        parameters: Optional[Dict[str, Any]] = None,
        tags: Optional[Dict[str, str]] = None,
        stage: str = "staging",
        framework: Optional[str] = None,
    ) -> ModelMetadata:
        """Register a model with the registry."""
        # Serialize model
        model_bytes = pickle.dumps(model)

        # Generate ID and version
        model_id = self._generate_id(name, model_bytes)

        # Determine version number
        if name not in self.versions:
            self.versions[name] = []
            version = "1"
        else:
            version = str(len(self.versions[name]) + 1)

        # Save artifact
        artifact_path = self.registry_path / name / f"v{version}.pkl"
        artifact_path.parent.mkdir(parents=True, exist_ok=True)
        with open(artifact_path, 'wb') as f:
            f.write(model_bytes)

        # Create metadata
        metadata = ModelMetadata(
            model_id=model_id,
            name=name,
            version=version,
            stage=stage,
            metrics=metrics or {},
            parameters=parameters or {},
            tags=tags or {},
            artifact_path=str(artifact_path),
            framework=framework or self._detect_framework(model),
        )

        self.versions[name].append(metadata)
        self._save_registry()

        return metadata

    def _detect_framework(self, model: Any) -> str:
        """Detect ML framework from model type."""
        module = type(model).__module__
        if "sklearn" in module:
            return "sklearn"
        elif "torch" in module:
            return "pytorch"
        elif "tensorflow" in module or "keras" in module:
            return "tensorflow"
        elif "xgboost" in module:
            return "xgboost"
        elif "lightgbm" in module:
            return "lightgbm"
        return "unknown"

    def load(self, name: str, version: Optional[str] = None, stage: Optional[str] = None) -> Any:
        """Load a model from the registry."""
        if name not in self.versions:
            raise ValueError(f"Model '{name}' not found in registry")

        # Find version
        metadata = None
        if version:
            for m in self.versions[name]:
                if m.version == version:
                    metadata = m
                    break
        elif stage:
            for m in sorted(self.versions[name], key=lambda x: x.version, reverse=True):
                if m.stage == stage:
                    metadata = m
                    break
        else:
            # Latest version
            metadata = max(self.versions[name], key=lambda x: int(x.version))

        if metadata is None:
            raise ValueError(f"Model '{name}' version '{version}' not found")

        # Load model
        with open(metadata.artifact_path, 'rb') as f:
            return pickle.load(f)

    def get_metadata(self, name: str, version: Optional[str] = None) -> ModelMetadata:
        """Get metadata for a model."""
        if name not in self.versions:
            raise ValueError(f"Model '{name}' not found")

        if version:
            for m in self.versions[name]:
                if m.version == version:
                    return m
            raise ValueError(f"Version '{version}' not found")

        return max(self.versions[name], key=lambda x: int(x.version))

    def list_models(self) -> List[str]:
        """List all registered model names."""
        return list(self.versions.keys())

    def list_versions(self, name: str) -> List[ModelMetadata]:
        """List all versions of a model."""
        if name not in self.versions:
            return []
        return sorted(self.versions[name], key=lambda x: int(x.version))

    def transition_stage(self, name: str, version: str, new_stage: str) -> ModelMetadata:
        """Transition a model to a new stage."""
        metadata = self.get_metadata(name, version)
        metadata.stage = new_stage
        self._save_registry()
        return metadata

    def compare_versions(self, name: str, version1: Optional[str] = None, version2: Optional[str] = None) -> Dict:
        """Compare two versions of a model."""
        versions = self.list_versions(name)
        if len(versions) < 2:
            return {"error": "Need at least 2 versions to compare"}

        v1 = next((v for v in versions if v.version == version1), versions[-2])
        v2 = next((v for v in versions if v.version == version2), versions[-1])

        comparison = {
            "version1": v1.version,
            "version2": v2.version,
            "metrics_diff": {},
            "parameters_diff": {},
        }

        # Compare metrics
        all_metrics = set(v1.metrics.keys()) | set(v2.metrics.keys())
        for metric in all_metrics:
            m1 = v1.metrics.get(metric, 0)
            m2 = v2.metrics.get(metric, 0)
            comparison["metrics_diff"][metric] = {
                "v1": m1,
                "v2": m2,
                "change": m2 - m1,
                "change_pct": ((m2 - m1) / m1 * 100) if m1 != 0 else None
            }

        return comparison

    def delete(self, name: str, version: Optional[str] = None) -> bool:
        """Delete a model or specific version."""
        if name not in self.versions:
            return False

        if version:
            self.versions[name] = [v for v in self.versions[name] if v.version != version]
            # Delete artifact
            artifact_path = self.registry_path / name / f"v{version}.pkl"
            if artifact_path.exists():
                artifact_path.unlink()
        else:
            # Delete all versions
            del self.versions[name]
            # Delete directory
            import shutil
            model_dir = self.registry_path / name
            if model_dir.exists():
                shutil.rmtree(model_dir)

        self._save_registry()
        return True


# Global registry instance
_registry: Optional[LocalModelRegistry] = None


def get_registry(path: Optional[str] = None) -> LocalModelRegistry:
    """Get or create the global model registry."""
    global _registry
    if _registry is None:
        _registry = LocalModelRegistry(path or "./model_registry")
    return _registry
